<?php
declare(strict_types=1);
require_once __DIR__ . '/business/config/customer_membership.php';
$pdo=role_portal_db();cm_ensure($pdo);$user=role_portal_require($pdo,'customer');$ctx=security_step17_context($pdo);$orgId=(int)$ctx['organization_id'];$orders=[];$customerCtx=cm_customer_context($pdo,$orgId,$user);$membership=$customerCtx['membership']??null;$offers=cm_promotions($pdo,$orgId,(string)$customerCtx['scope'],null);
$email=strtolower(trim((string)($user['email']??'')));$mobile=preg_replace('/\D+/','',(string)($user['mobile']??''))??'';if(strlen($mobile)>10&&str_starts_with($mobile,'91'))$mobile=substr($mobile,-10);
try{
    if(business_table_exists($pdo,'public_order_requests')&&($email!==''||$mobile!=='')){
        $where=[];$args=[$orgId];if($email!==''){$where[]='LOWER(email)=?';$args[]=$email;}if($mobile!==''){$where[]="REPLACE(REPLACE(REPLACE(REPLACE(mobile,' ',''),'-',''),'(',''),')','') LIKE ?";$args[]='%'.$mobile;}
        $sql="SELECT order_code,order_status,payment_status,delivery_mode,estimated_total,total_vp,delivery_charge,discount_amount,customer_price_mode,discount_label_code,created_at FROM public_order_requests WHERE organization_id=? AND (".implode(' OR ',$where).") ORDER BY id DESC LIMIT 10";
        $s=$pdo->prepare($sql);$s->execute($args);$orders=$s->fetchAll();
    }
}catch(Throwable){}
function customer_money(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
function customer_label(string $v):string{return ucwords(str_replace('_',' ',$v));}
function cp_style(string $style):string{return in_array($style,['green','bronze','silver','gold','blue','purple','coral'],true)?$style:'green';}
